    out = [row[:] for row in grid]
    marks = [[] for _ in range(w)]

    # A gap in a horizontal bar marks that bar's color in this column.
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            color = row[c - 1]
            if color and row[c] == 0 and row[c + 1] == color:
                out[r][c] = color
                marks[c].append((r, color))

    for c, column_marks in enumerate(marks):
        if not column_marks:
            continue
        column_marks.sort()
        # Horizontal bar crossings continue upward, each until the next bar.
        for i, (r, color) in enumerate(column_marks):
            top = column_marks[i - 1][0] + 1 if i else 0
            for rr in range(top, r):
